-- Build the benchmark metric catalog for the first reusable CBSA benchmark
-- surface. This starts with Act 1 profile metrics and cross-frame percentiles,
-- then grows as later analyses add benchmarkable metrics.

CREATE SCHEMA IF NOT EXISTS mart_benchmarking;

CREATE OR REPLACE TABLE mart_benchmarking.benchmark_metric_catalog AS
